#!/usr/bin/env bash
# tmux-powerkit theme — generated by aibox CLI from the active theme palette.
# Loaded via @powerkit_theme "custom" + @powerkit_custom_theme_path.
# Do NOT edit; re-run `aibox theme` to regenerate.

declare -gA THEME_COLORS=(
    # Core
    [background]="#0D1117"

    # Status bar
    [statusbar-bg]="#21252B"
    [statusbar-fg]="#E6EDF3"

    # Session (status-left)
    [session-bg]="#58A6FF"
    [session-fg]="#000000"
    [session-prefix-bg]="#F85149"
    [session-copy-bg]="#79C0FF"
    [session-search-bg]="#D29922"
    [session-command-bg]="#D2A8FF"

    # Windows
    [window-active-base]="#58A6FF"
    [window-active-style]="bold"
    [window-inactive-base]="#8B949E"
    [window-inactive-style]="dim"
    [window-activity-style]="dim"
    [window-bell-style]="bold"
    [window-zoomed-bg]="#79C0FF"

    # Panes
    [pane-border-active]="#58A6FF"
    [pane-border-inactive]="#8B949E"

    # Health / state segments (chevron color rotation source)
    [ok-base]="#799ABF"
    [good-base]="#3FB950"
    [info-base]="#79C0FF"
    [warning-base]="#D29922"
    [error-base]="#F85149"
    [disabled-base]="#8B949E"

    # Messages
    [message-bg]="#21252B"
    [message-fg]="#E6EDF3"

    # Popup & menu
    [popup-bg]="#21252B"
    [popup-fg]="#E6EDF3"
    [popup-border]="#58A6FF"
    [menu-bg]="#21252B"
    [menu-fg]="#E6EDF3"
    [menu-selected-bg]="#58A6FF"
    [menu-selected-fg]="#000000"
    [menu-border]="#58A6FF"
)

# Extra slots some plugins read directly — also derived from the palette so
# every chevron lands on a known-good bg.
declare -gA THEME_EXTRA=(
    [orange]="#DB6D28"
    [magenta]="#D2A8FF"
    [surface]="#21252B"
)
